def _sentences(tag, t, gaps):
    """Sentences of 6 words (0.30 s words, 0.05 s word gaps); gaps[i] = silence after sentence i."""
    ws = []
    for si, gap in enumerate(gaps):
        for wi in range(6):
            ws.append({"word": f"{tag}s{si}w{wi}" + ("." if wi == 5 else ""), "start": round(t, 2),
                       "end": round(t + 0.30, 2)})
            t += 0.35
        t += gap - 0.05
    return ws

